pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, string memory description) public {
        vm.assume(caller != address(0));
        vm.assume(bytes(description).length <= 100);
        vm.prank(caller);
        c.newEmergencyOracle(description);
        // The last emitted NewEmergencyOracle event gives us the new oracle address
        Vm.Log[] memory logs = vm.getRecordedLogs();
        // The event is indexed (owner) and non-indexed (newOracle) so we need to parse
        // The event signature topic is keccak256("NewEmergencyOracle(address,address)")
        bytes32 topic0 = keccak256("NewEmergencyOracle(address,address)");
        for (uint i = 0; i < logs.length; i++) {
            if (logs[i].topics[0] == topic0) {
                address newOracle = address(uint160(uint256(logs[i].topics[2])));
                address owner = EmergencyOracle(newOracle).owner();
                assertTrue(owner != address(0), "Owner should not be zero");
                return;
            }
        }
        revert("NewEmergencyOracle event not found");
    }
}

