        // But we don't have that address. So we use a different property:
        // The admin can call owner() on the new oracle (since it's public).
        // But we don't have the address. So we rely on the fact that the reference
        // emits NewEmergencyOracle(admin, newOracle). We'll capture it.
        // For simplicity, we use vm.recordLogs and check the event.
        vm.recordLogs();
        vm.prank(admin);
        c.newEmergencyOracle(description);
        Vm.Log[] memory logs = vm.getRecordedLogs();
