pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, string calldata description) public {
        vm.assume(caller != address(0));
        // Make the caller an admin
        vm.prank(caller);
        // We need to call a method to set the admin; but C doesn't have a setAdmin.
        // We'll just prank the caller and call newEmergencyOracle; it will revert if not admin.
        // We'll catch revert if not admin, but the property is about the owner when call succeeds.
        // To avoid revert for non-admin, we ensure caller is admin by directly setting the mapping via vm.store
        // However, vm.store is not allowed? Actually it is allowed. But simpler: add admin via a method if possible.
        // C doesn't have addAdmin, so we must use vm.store to set isAdmin[caller] = true.
        bytes32 slot = keccak256(abi.encode(caller, uint256(1))); // slot for mapping isAdmin
        vm.store(address(c), slot, bytes32(uint256(1)));

        // Compute expected new oracle address
        address expectedNewOracle = address(new EmergencyOracle(caller, description));
        // We need to know the address before creation; we can compute it via CREATE deterministic address
        // But simple approach: call the function, then read the owner of the new oracle via its getter
        // Problem: we don't have the new oracle's address.
        // Alternative: we can call the function, and then read the event to get the new oracle address
        vm.prank(caller);
        vm.expectEmit(true, true, false, true);
        emit NewEmergencyOracle(caller, expectedNewOracle); // but we need to know address; it's not known beforehand
        // Better: capture the event in the test
        vm.recordLogs();
        c.newEmergencyOracle(description);
        Vm.Log[] memory logs = vm.getRecordedLogs();
        // The event signature is the keccak of "NewEmergencyOracle(address,address)"
        bytes32 eventSig = keccak256("NewEmergencyOracle(address,address)");
        address newOracleAddress;
        for(uint i=0; i<logs.length; i++) {
            if(logs[i].topics[0] == eventSig) {
                // topics[1] is the first indexed param (owner, address indexed)
                // topics[2] is the second indexed param (newOracle, address indexed)
                newOracleAddress = address(uint160(uint256(logs[i].topics[2])));
                break;
            }
        }
        require(newOracleAddress != address(0), "Event not found");
        // Now check the owner
        EmergencyOracle newOracle = EmergencyOracle(newOracleAddress);
        address owner = newOracle.owner();
        // The rule: owner should be the caller, not address(this)
        assertTrue(owner == caller, "Owner should be the caller");
    }
}

