pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(string calldata description) public {
        // Make the caller an admin
        vm.prank(address(this));
        c.isAdmin(address(this)); // This call is just to ensure address(this) is admin; but isAdmin is a mapping, we need to set it.
        // Actually, we need to set isAdmin[caller] to true. Since isAdmin is public, we can't set it directly, but we can call the admin setter if any? There is no setter. 
        // So we assume the caller (this test contract) is already admin. But we need to set it: we can use vm.store to set the mapping.
        // For simplicity, we use vm.assume to assume the caller is admin, but we can also use vm.prank and call the contract to set admin.
        // Since the contract has no setter, we use vm.store to set the mapping slot.
        // The slot for mapping is keccak256(abi.encode(key, slot)).
        // slot for isAdmin is 0.
        bytes32 slot = keccak256(abi.encode(address(this), uint256(0)));
        vm.store(address(c), slot, bytes32(uint256(1)));

        // Call newEmergencyOracle
        c.newEmergencyOracle(description);

        // The new oracle's address is emitted; we need to get it from the event.
        // We can use vm.recordLogs() and then get the last event.
        // Actually, we need to capture the event. Let's use vm.recordLogs() after deployment but before call.
        // Better: we can compute the address of the new oracle deterministically.
        // EmergencyOracle constructor: address = keccak256(abi.encodePacked(byte(0xff), address(c), nonce, keccak256(abi.encode(EmergencyOracle, address(this), description))))[12:].
        // But nonce depends on how many contracts created by C. Since we just deployed C, nonce=1.
        // Let's compute the expected address.
        address expectedNewOracle = address(uint160(uint256(keccak256(abi.encodePacked(
            bytes1(0xff),
            address(c),
            bytes32(uint256(1)), // nonce
            keccak256(abi.encodePacked(
                type(EmergencyOracle).creationCode,
                abi.encode(address(this), description)
            ))
        ))));

        // But we don't have import of EmergencyOracle. We can get the event.
        // Let's use vm.recordLogs() after the call.
        Vm.Log[] memory entries = vm.getRecordedLogs();
        address newOracle = address(uint160(uint256(entries[entries.length-1].topics[2]))); // from NewEmergencyOracle event

        // Check that the new oracle's owner is admin (isAdmin[owner] should be true)
        // But we can't call EmergencyOracle's owner() directly because EmergencyOracle is not imported.
        // However, we can use the emitted event in P: the newOracle's owner is the caller (address(this)).
        // In M: the newOracle's owner is address(c).
        // So we check that isAdmin[owner] is true. To get owner, we can use the address of the new oracle and call owner() via low-level call.
        (bool success, bytes memory data) = newOracle.staticcall(abi.encodeWithSignature("owner()"));
        require(success);
        address owner = abi.decode(data, (address));

        // The rule: after calling newEmergencyOracle, the owner of the new oracle must be an admin (isAdmin[owner] == true)
        assertTrue(c.isAdmin(owner));
    }
}

