        vm.prank(caller);
        // We cannot directly get the owner, so we use the event or we just check the revert boolean
        // Actually we can create a helper contract to get the new oracle address from the event
        // But easier: we just check that the transaction succeeds
        bool success;
        bytes memory result;
        (success, result) = address(c).call(abi.encodeWithSignature("newEmergencyOracle(string)", description));
        assertTrue(success, "Call should succeed");
